<?php $this->layout('_theme'); ?>
<div class="support-container"><nav class="support-breadcrumb"><a href="<?= url('/suporte') ?>">Central de Ajuda</a><ion-icon name="chevron-forward-outline"></ion-icon><a href="<?= url('/suporte/'.$category->uri) ?>"><?= htmlspecialchars($category->title) ?></a><ion-icon name="chevron-forward-outline"></ion-icon><span><?= htmlspecialchars($article->title) ?></span></nav><div class="support-content-layout"><aside class="support-sidebar"><strong>Assuntos</strong><?php foreach($categories as $item): ?><a class="<?= $item->id==$category->id?'active':'' ?>" href="<?= url('/suporte/'.$item->uri) ?>"><ion-icon name="<?= htmlspecialchars($item->icon) ?>"></ion-icon><?= htmlspecialchars($item->title) ?></a><?php endforeach; ?></aside><article class="support-article"><small><?= htmlspecialchars($category->title) ?></small><h1><?= htmlspecialchars($article->title) ?></h1><p class="support-lead"><?= htmlspecialchars($article->summary) ?></p><?php if($article->cover): ?><img class="support-cover" src="<?= image($article->cover,1200) ?>" alt="<?= htmlspecialchars($article->title) ?>"><?php endif; ?><div class="support-prose"><?= $article->content ?></div><section class="support-vote"><strong>Esta matéria foi útil?</strong><form action="<?= url('/suporte/avaliar/'.$article->id) ?>" method="post"><?= csrf_input() ?><button name="vote" value="yes"><ion-icon name="thumbs-up-outline"></ion-icon> Sim</button><button name="vote" value="no"><ion-icon name="thumbs-down-outline"></ion-icon> Não</button></form><p aria-live="polite"></p></section><?php if($related): ?><section class="support-related"><h2>Matérias relacionadas</h2><?php foreach($related as $item): ?><a href="<?= url('/suporte/'.$category->uri.'/'.$item->uri) ?>"><?= htmlspecialchars($item->title) ?><ion-icon name="arrow-forward-outline"></ion-icon></a><?php endforeach; ?></section><?php endif; ?></article></div></div>
<?php $this->start('scripts') ?><script>document.querySelector('.support-vote form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter,data=new FormData(e.currentTarget);data.set('vote',button.value);const response=await fetch(e.currentTarget.action,{method:'POST',body:data});const result=await response.json();document.querySelector('.support-vote p').textContent=result.message||'';if(result.success)e.currentTarget.querySelectorAll('button').forEach(item=>item.disabled=true)});</script><?php $this->stop() ?>
